/* ===================================================
   GLOBAL HEADER ARCHITECTURE (Header Site Part 13859)
   =================================================== */

/* 1. Header Outer Container: Sticky, Glassmorphism, Clean Background */
.elementor-element-79a3f82,
header.elementor-13859,
.elementor-13859 {
    width: 100% !important;
    background-color: rgba(249, 247, 242, 0.98) !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
    border-bottom: 1px solid rgba(22, 28, 34, 0.08) !important;
    box-shadow: 0 4px 20px rgba(30, 37, 43, 0.05) !important;
    padding: 0.45rem 1.25rem !important;
    position: sticky !important;
    top: 0 !important;
    inset-block-start: 0px !important;
    z-index: 1000 !important;
    box-sizing: border-box !important;
}

/* 2. Header Inner Row: Align items horizontally, space-between */
.elementor-element-5e544b69 {
    display: flex !important;
    flex-direction: row !important;
    justify-content: space-between !important;
    align-items: center !important;
    max-width: 1400px !important;
    margin: 0 auto !important;
    width: 100% !important;
    height: auto !important;
    min-height: 54px !important;
    flex-wrap: nowrap !important;
    gap: 0.8rem !important;
    box-sizing: border-box !important;
}

/* 3. Brand Box (Logo + Title + Subtitle) */
.elementor-element-1a85c756 {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    gap: 0.65rem !important;
    flex: 0 0 auto !important;
    flex-shrink: 0 !important;
}
.elementor-element-7b2e4b47,
.elementor-element-1a85c756 img {
    width: 36px !important;
    height: 36px !important;
    max-width: 36px !important;
    max-height: 36px !important;
    object-fit: contain !important;
    display: block !important;
    flex-shrink: 0 !important;
    filter: drop-shadow(0 2px 4px rgba(0,0,0,0.12)) !important;
}
.elementor-element-46c38472 {
    display: flex !important;
    flex-direction: column !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
}
.elementor-element-6d470876 {
    font-family: 'Playfair Display', Georgia, serif !important;
    font-size: 1.15rem !important;
    font-weight: 700 !important;
    letter-spacing: -0.01em !important;
    color: #151C22 !important;
    line-height: 1.1 !important;
    margin: 0 !important;
    white-space: nowrap !important;
}
.elementor-element-23395620 {
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.58rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.12em !important;
    color: #7B5800 !important;
    text-transform: uppercase !important;
    margin: 2px 0 0 0 !important;
    line-height: 1 !important;
    white-space: nowrap !important;
}

/* 4. Desktop Navigation Links */
.elementor-element-e39931c {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-end !important;
    gap: 0.15rem !important;
    flex-wrap: nowrap !important;
    flex: 1 1 auto !important;
    margin: 0 !important;
    width: auto !important;
}
.elementor-element-e39931c .e-button-base,
.elementor-element-e39931c a {
    background: transparent !important;
    background-color: transparent !important;
    color: #1A242D !important;
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.78rem !important;
    font-weight: 600 !important;
    box-shadow: none !important;
    border: none !important;
    padding: 0.35rem 0.5rem !important;
    border-radius: 6px !important;
    transition: all 0.2s ease !important;
    white-space: nowrap !important;
    display: inline-flex !important;
    align-items: center !important;
    text-decoration: none !important;
}
.elementor-element-e39931c .e-button-base:hover,
.elementor-element-e39931c a:hover {
    color: #7B5800 !important;
    background: rgba(123, 88, 0, 0.08) !important;
    background-color: rgba(123, 88, 0, 0.08) !important;
}

/* 5. Header Action Button (Colaborar) */
.elementor-element-23cca5d9 {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    flex: 0 0 auto !important;
    flex-shrink: 0 !important;
    margin-left: 0.4rem !important;
}
.elementor-element-23cca5d9 a,
.elementor-element-2ce90fc2 {
    background: #7B5800 !important;
    background-color: #7B5800 !important;
    color: #FFFFFF !important;
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.72rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.04em !important;
    text-transform: uppercase !important;
    padding: 0.4rem 0.85rem !important;
    border-radius: 6px !important;
    box-shadow: 0 4px 12px rgba(123, 88, 0, 0.25) !important;
    text-decoration: none !important;
    white-space: nowrap !important;
    transition: all 0.2s ease !important;
    display: inline-flex !important;
    align-items: center !important;
    border: none !important;
}
.elementor-element-23cca5d9 a:hover,
.elementor-element-2ce90fc2:hover {
    background: #5D4300 !important;
    background-color: #5D4300 !important;
    color: #FFFFFF !important;
    transform: translateY(-2px) !important;
    box-shadow: 0 6px 16px rgba(123, 88, 0, 0.35) !important;
}

/* ===================================================
   RESPONSIVE & MOBILE MENU (DRAWER & TOGGLE)
   =================================================== */

/* Desktop view: Hide mobile drawer and toggle button completely */
@media (min-width: 1025px) {
    #lastras-mobile-toggle-btn,
    #lastras-mobile-drawer,
    .lastras-mobile-nav-toggle-wrap,
    .elementor-element-lastras_mobile_nav_widget,
    [data-id="lastras_mobile_nav_widget"],
    .lastras-mobile-drawer {
        display: none !important;
        visibility: hidden !important;
        opacity: 0 !important;
        pointer-events: none !important;
    }
    .elementor-element-e39931c {
        display: flex !important;
    }
    .elementor-element-23cca5d9 {
        display: flex !important;
    }
}

/* Tablet & Mobile: Show hamburger toggle and handle mobile drawer */
@media (max-width: 1024px) {
    .elementor-element-79a3f82 {
        padding: 0.4rem 0.85rem !important;
        position: sticky !important;
        top: 0 !important;
        z-index: 99999 !important;
        background: rgba(249, 247, 242, 0.98) !important;
        backdrop-filter: blur(16px) !important;
        -webkit-backdrop-filter: blur(16px) !important;
        border-bottom: 1px solid rgba(22, 28, 34, 0.08) !important;
        box-shadow: 0 4px 18px rgba(0, 0, 0, 0.05) !important;
        box-sizing: border-box !important;
        width: 100% !important;
    }
    .elementor-element-5e544b69 {
        display: flex !important;
        flex-direction: row !important;
        justify-content: space-between !important;
        align-items: center !important;
        width: 100% !important;
        min-height: 44px !important;
        flex-wrap: nowrap !important;
        box-sizing: border-box !important;
        gap: 0.4rem !important;
    }
    .elementor-element-1a85c756 {
        display: flex !important;
        flex-direction: row !important;
        align-items: center !important;
        gap: 0.5rem !important;
        flex: 1 1 auto !important;
        max-width: calc(100% - 50px) !important;
        min-width: 0 !important;
    }
    .elementor-element-7b2e4b47,
    .elementor-element-1a85c756 img {
        width: 32px !important;
        height: 32px !important;
        max-width: 32px !important;
        max-height: 32px !important;
        flex-shrink: 0 !important;
        display: block !important;
    }
    .elementor-element-46c38472 {
        display: flex !important;
        flex-direction: column !important;
        justify-content: center !important;
        flex-shrink: 1 !important;
        min-width: 0 !important;
    }
    .elementor-element-6d470876 {
        font-family: 'Playfair Display', Georgia, serif !important;
        font-size: 1.05rem !important;
        font-weight: 700 !important;
        color: #151C22 !important;
        line-height: 1.15 !important;
        white-space: nowrap !important;
        margin: 0 !important;
    }
    .elementor-element-23395620 {
        font-family: 'Plus Jakarta Sans', sans-serif !important;
        font-size: 0.5rem !important;
        font-weight: 700 !important;
        letter-spacing: 0.06em !important;
        color: #7B5800 !important;
        text-transform: uppercase !important;
        white-space: nowrap !important;
        margin: 1px 0 0 0 !important;
        line-height: 1 !important;
    }
    .elementor-element-e39931c,
    .elementor-element-23cca5d9 {
        display: none !important;
    }
    .elementor-element-lastras_mobile_nav_widget,
    [data-id="lastras_mobile_nav_widget"] {
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        flex: 0 0 42px !important;
        width: 42px !important;
        min-width: 42px !important;
        max-width: 42px !important;
        height: 42px !important;
        margin: 0 0 0 auto !important;
        padding: 0 !important;
    }
    .lastras-mobile-nav-toggle-wrap {
        display: flex !important;
        align-items: center !important;
        justify-content: center !important;
        width: 42px !important;
        height: 42px !important;
        margin: 0 !important;
        padding: 0 !important;
    }
    #lastras-mobile-toggle-btn {
        display: flex !important;
        flex-direction: column !important;
        justify-content: center !important;
        align-items: center !important;
        gap: 4px !important;
        width: 38px !important;
        height: 38px !important;
        padding: 0 !important;
        background: #FFFFFF !important;
        border: 1px solid rgba(123, 88, 0, 0.35) !important;
        border-radius: 8px !important;
        box-shadow: 0 2px 8px rgba(0,0,0,0.08) !important;
        cursor: pointer !important;
        box-sizing: border-box !important;
    }
    #lastras-mobile-toggle-btn:active {
        transform: scale(0.92);
        background: rgba(123, 88, 0, 0.12) !important;
    }
    #lastras-mobile-toggle-btn .hamburger-bar {
        display: block !important;
        width: 18px !important;
        height: 2px !important;
        background-color: #151C22 !important;
        border-radius: 2px !important;
        transition: all 0.25s ease !important;
    }
    #lastras-mobile-toggle-btn.is-active .hamburger-bar:nth-child(1) {
        transform: translateY(6px) rotate(45deg) !important;
    }
    #lastras-mobile-toggle-btn.is-active .hamburger-bar:nth-child(2) {
        opacity: 0 !important;
    }
    #lastras-mobile-toggle-btn.is-active .hamburger-bar:nth-child(3) {
        transform: translateY(-6px) rotate(-45deg) !important;
    }
}

/* Mobile Drawer Styles */
.lastras-mobile-drawer {
    position: fixed !important;
    top: 52px !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    background: rgba(249, 247, 242, 0.99) !important;
    backdrop-filter: blur(20px) !important;
    -webkit-backdrop-filter: blur(20px) !important;
    z-index: 99998 !important;
    overflow-y: auto !important;
    -webkit-overflow-scrolling: touch !important;
    transform: translateY(-100%);
    opacity: 0;
    pointer-events: none;
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.25s ease !important;
    padding: 1.25rem 1.5rem 3rem 1.5rem !important;
    box-sizing: border-box !important;
    border-bottom: 2px solid #7B5800 !important;
    box-shadow: 0 20px 40px rgba(0,0,0,0.15) !important;
}
.lastras-mobile-drawer.is-open {
    transform: translateY(0) !important;
    opacity: 1 !important;
    pointer-events: auto !important;
}
.lastras-mobile-drawer-inner {
    max-width: 480px !important;
    margin: 0 auto !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 0.4rem !important;
}
.lastras-mobile-drawer-header {
    display: flex !important;
    justify-content: space-between !important;
    align-items: center !important;
    padding-bottom: 0.75rem !important;
    border-bottom: 1px solid rgba(22, 28, 34, 0.1) !important;
    margin-bottom: 0.4rem !important;
}
.lastras-drawer-title {
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.7rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.15em !important;
    color: #7B5800 !important;
    text-transform: uppercase !important;
}
.lastras-drawer-close {
    background: transparent !important;
    border: none !important;
    font-size: 1.3rem !important;
    color: #718096 !important;
    cursor: pointer !important;
    padding: 0.25rem 0.5rem !important;
}
.lastras-mobile-drawer-nav {
    display: flex !important;
    flex-direction: column !important;
    gap: 0.35rem !important;
}
.lastras-drawer-link {
    display: flex !important;
    align-items: center !important;
    gap: 0.85rem !important;
    padding: 0.75rem 1rem !important;
    border-radius: 10px !important;
    text-decoration: none !important;
    color: #151C22 !important;
    background: rgba(255, 255, 255, 0.7) !important;
    border: 1px solid rgba(22, 28, 34, 0.06) !important;
    transition: all 0.2s ease !important;
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.88rem !important;
    font-weight: 600 !important;
}
.lastras-drawer-link:active {
    background: rgba(123, 88, 0, 0.12) !important;
    border-color: #7B5800 !important;
}
.lastras-drawer-divider {
    height: 1px !important;
    background: rgba(22, 28, 34, 0.1) !important;
    margin: 0.5rem 0 !important;
}
.lastras-drawer-cta {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 0.6rem !important;
    padding: 0.85rem 1rem !important;
    border-radius: 10px !important;
    text-decoration: none !important;
    color: #FFFFFF !important;
    background: #7B5800 !important;
    font-family: 'Plus Jakarta Sans', sans-serif !important;
    font-size: 0.88rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.04em !important;
    text-transform: uppercase !important;
    box-shadow: 0 4px 14px rgba(123, 88, 0, 0.3) !important;
}
body.lastras-menu-locked {
    overflow: hidden !important;
}
